describe('Unread Notification Visual Distinction', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should visually distinguish unread notifications with a distinct badge or styling', () => {
    // Intercept API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify unread notification is visible and styled distinctly
    cy.get('[data-testid="notification-item-unread"]').should('be.visible');
    cy.get('[data-testid="notification-item-unread"]').should('have.class', 'unread-badge');
    cy.get('[data-testid="notification-item-unread"]').should('contain', 'New message from John');

    // Verify read notification is visible but lacks the distinct unread styling
    cy.get('[data-testid="notification-item-read"]').should('be.visible');
    cy.get('[data-testid="notification-item-read"]').should('not.have.class', 'unread-badge');
    cy.get('[data-testid="notification-item-read"]').should('contain', 'Email from Sarah');

    // Verify unread notification has a distinct background or border
    cy.get('[data-testid="notification-item-unread"]').should('have.css', 'background-color', 'rgb(255, 240, 255)');
    cy.get('[data-testid="notification-item-read"]').should('have.css', 'background-color', 'rgb(255, 255, 255)');
  });

  it('should handle edge case of no unread notifications and display appropriate message', () => {
    // Intercept API call with empty unread notifications
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          { id: 1, type: 'read', content: 'Old email', read: true },
          { id: 2, type: 'read', content: 'Meeting reminder', read: true },
        ],
        unreadCount: 0
      }
    }).as('getNotificationsEmpty');
    cy.wait('@getNotificationsEmpty');

    // Verify no unread notification items are displayed
    cy.get('[data-testid="notification-item-unread"]').should('not.exist');

    // Verify "No unread notifications" message is displayed
    cy.get('[data-testid="no-unread-notifications-message"]').should('be.visible');
    cy.get('[data-testid="no-unread-notifications-message"]').should('contain', 'You have no unread notifications');

    // Verify unread count badge is not present or shows 0
    cy.get('[data-testid="unread-count-badge"]').should('be.visible');
    cy.get('[data-testid="unread-count-badge"]').should('contain', '0');
  });
});
